import {getGarment} from './core/garments.js';

const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function motifThumbnail(motif){
  const grid=motif.grid,w=grid[0].length,h=grid.length;
  // Sample large motifs for lightweight library previews; exports keep every stitch.
  const step=Math.max(1,Math.ceil(Math.max(w,h)/48));let cells='';
  for(let y=0;y<h;y+=step)for(let x=0;x<w;x+=step)cells+=`<rect x="${x}" y="${y}" width="${Math.min(step,w-x)}" height="${Math.min(step,h-y)}" fill="${esc(grid[y][x])}"/>`;
  return `<svg class="motif-thumbnail" viewBox="0 0 ${w} ${h}" aria-hidden="true" shape-rendering="crispEdges">${cells}</svg>`;
}

export function patternLibrarySection(project,count){return `<section class="section library-section"><h3 class="section-title">我的提花 <span class="muted">${count} 个已保存</span></h3><div class="draft-title">${esc(project.draftMotifName||'未命名提花')}<span>当前画布</span></div><div class="library-actions"><button class="btn soft small" data-action="save-motif">保存提花</button><button class="btn small" data-action="save-motif-as">另存为</button><button class="btn small" data-action="new-motif">新建提花</button><button class="btn small" data-action="motif-library">打开提花库</button></div><p class="hint">每个提花独立保存，可在多个工程中反复使用。</p></section>`;}

export function placementSection(project,selectedId){
  const items=(project.motifPlacements||[]).filter(p=>p.garmentId===project.garmentId),selected=items.find(p=>p.id===selectedId);
  return `<section class="section placement-section"><h3 class="section-title">图案放置 <span class="muted">${items.length} 个提花</span></h3><button class="btn full soft" data-action="choose-placement">＋ 从提花库添加</button><label class="field placement-mode"><span>衣片底图</span><select id="arrangement-mode" aria-label="衣片底图"><option value="custom" ${project.arrangement==='custom'?'selected':''}>自由放置多个提花</option><option value="legacy" ${project.arrangement!=='custom'?'selected':''}>当前画布自动铺放</option></select></label>${project.arrangement==='custom'?`<label class="field fabric-field"><span>衣片底色</span><input type="color" id="fabric-color" aria-label="衣片底色" value="${esc(project.fabricColor||project.palette[0])}"></label>`:`<select class="select" id="placement-left" aria-label="提花放置方式"><option value="repeat" ${project.placement==='repeat'?'selected':''}>重复铺满裁片</option><option value="center" ${project.placement==='center'?'selected':''}>单幅图案居中</option></select>`}<div class="placed-list">${items.map((p,i)=>`<button class="placed-item ${p.id===selectedId?'selected':''}" data-select-placement="${esc(p.id)}" aria-label="选择已放置提花 ${esc(p.name)} ${i+1}">${motifThumbnail(p)}<span><b>${esc(p.name)}</b><small>第 ${p.stitch} 针 · 第 ${p.row} 行</small></span><em>${i+1}</em></button>`).join('')}</div>${selected?`<div class="placement-settings"><p class="placement-caption">正在调整：${esc(selected.name)}</p><div class="form-row">${positionField('placement-stitch','右侧起针',selected.stitch,400)}${positionField('placement-row','底部起行',selected.row,600)}</div><p class="hint">以花样右下角为起点。拖动框内花样，或点击其他针位重新定位。</p><label class="toggle-label"><input type="checkbox" id="placement-transparent" ${selected.transparentBackground?'checked':''}>不绘制提花底色</label><div class="placement-buttons"><button class="btn small" data-placement-action="move">移动位置</button><button class="btn small" data-placement-action="duplicate">再放一个</button><button class="btn small" data-placement-action="flip">左右翻转</button><button class="btn small" data-placement-action="front">移到最上层</button><button class="btn small danger" data-placement-action="remove">移除</button></div></div>`:'<p class="hint">添加后选择花样，在图解上安排位置。后添加的提花显示在上层。</p>'}</section>`;
}
function positionField(id,label,value,max){return `<label class="field"><span>${label}</span><div class="input-wrap"><input type="number" id="${id}" aria-label="${label}" min="1" max="${max}" step="1" value="${value}"></div></label>`;}

export function motifLibraryHTML(motifs,mode){return `<div class="library-modal-actions"><button class="btn small" id="import-motif">导入提花文件</button>${mode==='edit'?'<button class="btn soft small" id="library-new-motif">新建提花</button>':''}</div><p>${mode==='place'?'选择一个提花加入当前衣片，同一花样可以重复加入。':'独立保存的花样，可打开继续绘制，也可下载备份。'}</p><div class="motif-library-grid">${motifs.map(m=>`<article class="motif-card">${motifThumbnail(m)}<h3>${esc(m.name)}</h3><p>${m.grid[0].length} 针 × ${m.grid.length} 行</p><div class="motif-card-actions"><button class="btn soft small" data-library-use="${esc(m.id)}">${mode==='place'?'加入衣片':'打开绘制'}</button><button class="btn small" data-library-download="${esc(m.id)}">下载</button><button class="tool" data-library-remove="${esc(m.id)}" aria-label="删除提花 ${esc(m.name)}">×</button></div></article>`).join('')}</div>${motifs.length?'':'<div class="empty-library">还没有保存的提花。<br>在提花设计页画一个花样，点击「保存提花」。<button class="btn soft" id="go-draw-motif">去绘制提花</button></div>'}`;}

export function projectManagerHTML(workspace){return `<div class="library-modal-actions"><button class="btn primary" id="new-project">＋ 新建工程</button><button class="btn" id="restore">导入工程</button><button class="btn" id="backup-workspace">全部备份</button></div><p>每个工程单独保留版型、尺寸、图解与标注。提花库由所有工程共用。</p><div class="project-list">${workspace.projects.map(entry=>`<article class="project-card ${entry.id===workspace.activeProjectId?'current':''}"><div><h3>${esc(entry.project.name)} ${entry.id===workspace.activeProjectId?'<small>当前</small>':''}</h3><p>${esc(getGarment(entry.project.garmentId).name)} · ${entry.project.measurements.width} × ${entry.project.measurements.height} cm</p></div><div class="project-card-actions"><button class="btn soft small" data-open-project="${esc(entry.id)}">打开</button><button class="btn small" data-download-project="${esc(entry.id)}">备份</button><button class="tool" data-delete-project="${esc(entry.id)}" aria-label="删除工程 ${esc(entry.project.name)}" ${workspace.projects.length===1?'disabled':''}>×</button></div></article>`).join('')}</div>`;}
